<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ورود · بلوکام</title>@vite(['resources/css/app.css','resources/js/app.js'])</head><body class="min-h-screen bg-slate-100 grid place-items-center p-6"><main class="w-full max-w-md rounded-2xl bg-white p-8 shadow-xl"><h1 class="text-2xl font-black">ورود به بلوکام</h1><p class="mt-2 text-sm text-slate-500">با شماره موبایل وارد شوید.</p><form id="otp-form" class="mt-8 space-y-4">@csrf<input id="mobile" required inputmode="tel" placeholder="09121234567" class="w-full rounded-xl border p-3"><div id="code-wrap" class="hidden"><input id="code" inputmode="numeric" maxlength="6" placeholder="کد ۶ رقمی" class="w-full rounded-xl border p-3"></div><button class="w-full rounded-xl bg-blue-600 p-3 font-bold text-white">ادامه</button><p id="message" class="text-sm text-red-600"></p></form></main><script>const f=document.querySelector('#otp-form'),m=document.querySelector('#message'),c=document.querySelector('#code-wrap');let challenge;f.addEventListener('submit',async e=>{e.preventDefault();m.textContent='';const body={mobile:document.querySelector('#mobile').value};if(c.classList.contains('hidden')){const r=await fetch('/auth/otp/request',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('[name=_token]').value},body:JSON.stringify(body)});const d=await r.json();if(!r.ok){m.textContent=d.message||'خطا در ارسال کد';return}challenge=d.challenge_id;c.classList.remove('hidden');return}body.code=document.querySelector('#code').value;body.challenge_id=challenge;const r=await fetch('/auth/otp/verify',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('[name=_token]').value},body:JSON.stringify(body)});if(r.ok) location.href='/';else{const d=await r.json();m.textContent=d.message||'کد واردشده معتبر نیست.'}})</script></body></html>
